from django.db import migrations, models
from django.db.models import Sum


def split_printed_stock(apps, schema_editor):
    """Tickets already printed become physical tickets, and their number leaves
    the online stock for the physical one: the total per ticket type is the same."""
    Ticket = apps.get_model("tickets", "Ticket")
    TicketType = apps.get_model("tickets", "TicketType")
    OrderItem = apps.get_model("tickets", "OrderItem")
    Ticket.objects.filter(order__print_batch__isnull=False).update(channel="physical")
    for tt in TicketType.objects.all():
        printed = OrderItem.objects.filter(
            ticket_type=tt, order__print_batch__isnull=False, order__stock_state="sold",
        ).aggregate(n=Sum("quantity"))["n"] or 0
        if printed:
            TicketType.objects.filter(pk=tt.pk).update(
                printed=printed, physical_capacity=printed,
                sold=max(tt.sold - printed, 0), capacity=max(tt.capacity - printed, 0),
            )


def merge_printed_stock(apps, schema_editor):
    TicketType = apps.get_model("tickets", "TicketType")
    for tt in TicketType.objects.all():
        TicketType.objects.filter(pk=tt.pk).update(sold=tt.sold + tt.printed, capacity=tt.capacity + tt.physical_capacity)


